import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0]); M = int(data[1])
    arr = [int(x) for x in data[2:2 + n]]
    MOD = 10 ** 9 + 7
    # dp[v] for v in 0..M+1, indices 0 and M+1 are padding (always 0)
    dp = [0] * (M + 2)
    if arr[0] == 0:
        for v in range(1, M + 1):
            dp[v] = 1
    else:
        dp[arr[0]] = 1
    for i in range(1, n):
        if arr[i] == 0:
            dp = [0] + [(a + b + c) % MOD for a, b, c in zip(dp, dp[1:], dp[2:])] + [0]
        else:
            v = arr[i]
            nd = [0] * (M + 2)
            nd[v] = (dp[v - 1] + dp[v] + dp[v + 1]) % MOD
            dp = nd
    print(sum(dp) % MOD)

